import heapq
from collections import defaultdict

def shortest_dag_brute(n, edges, src=0):
    """Works on general digraphs with w≥0 — does not use DAG structure."""
    g = defaultdict(list)
    for u, v, w in edges:
        g[u].append((v, w))
    dist = [float('inf')] * n
    dist[src] = 0
    h = [(0, src)]
    while h:
        d, u = heapq.heappop(h)
        if d != dist[u]:
            continue
        for v, w in g[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(h, (nd, v))
    return [-1 if d == float('inf') else d for d in dist]

from collections import defaultdict, deque

def shortest_path_dag(n, edges, src=0):
    g = defaultdict(list)
    indeg = [0] * n
    for u, v, w in edges:
        g[u].append((v, w))
        indeg[v] += 1

    # Kahn topo
    q = deque([i for i in range(n) if indeg[i] == 0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v, _ in g[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    dist = [float('inf')] * n
    dist[src] = 0
    for u in topo:
        if dist[u] == float('inf'):
            continue
        for v, w in g[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    return [-1 if d == float('inf') else int(d) for d in dist]

