#include <bits/stdc++.h>
using namespace std;

vector<int> shortestPathDag(int n, vector<array<int,3>> edges, int src = 0) {
    vector<vector<pair<int,int>>> g(n);
    vector<int> indeg(n, 0);
    for (auto &e : edges) {
        int u = e[0], v = e[1], w = e[2];
        g[u].push_back({v, w});
        indeg[v]++;
    }

    queue<int> q;
    for (int i = 0; i < n; i++) if (indeg[i] == 0) q.push(i);
    vector<int> topo;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (auto [v, w] : g[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }

    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    dist[src] = 0;
    for (int u : topo) {
        if (dist[u] == INF) continue;
        for (auto [v, w] : g[u]) {
            if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
        }
    }

    vector<int> ans(n);
    for (int i = 0; i < n; i++) ans[i] = dist[i] == INF ? -1 : (int)dist[i];
    return ans;
}
